<?php
declare(strict_types=1);
if (!defined('MTX_FRONT_CONTROLLER')) { http_response_code(404); exit; }
use MTX\{Http,Security,Releases,GameIds};
$app=require dirname(__DIR__,2).'/src/bootstrap.php';
Http::method('GET'); Security::session($app);
if (!Security::loggedIn($app)) Http::redirect($app->path('/admin/login.php'));
header('Cache-Control: no-store');
$s=$app->store->read();
GameIds::rejectLegacyFields($_GET);
$g=GameIds::resolve($s,$_GET+['game_id'=>1]);
$gameID=$g['game_id'];
$key=$g['app_key'];
$releases=array_reverse(array_values(array_filter($s['releases'],fn($r)=>$r['app_key']===$key)));
$current=$g['current_release_id']?Releases::release($s,$g['current_release_id']):null;
$url=$app->url('/api/update.php');
$flash=$_SESSION['flash']??''; unset($_SESSION['flash']);
function e(mixed $v): string { return Http::escape($v); }
function fields(string $action,?int $gameID=null,array $extra=[]): void {
    $values=['csrf'=>$_SESSION['csrf'],'action'=>$action]+$extra;
    if ($gameID!==null) $values['game_id']=$gameID;
    foreach ($values as $name=>$value) echo '<input type="hidden" name="'.e($name).'" value="'.e($value).'">';
}
function dateLabel(string $value): string { return (new DateTimeImmutable($value))->setTimezone(new DateTimeZone('Asia/Shanghai'))->format('Y-m-d H:i'); }
function sizeLabel(?int $size): string { return $size===null?'—':number_format($size/1048576,2).' MiB'; }
$labels=['draft'=>'等待自动处理','ready'=>'待发布','published'=>'已发布','withdrawn'=>'已下架'];
?>
