<?php MTX\AdminLayout::begin($app,'游戏更新','releases'); ?><main class="content"><section class="game-switcher panel"><label for="game-switch">当前游戏</label><select id="game-switch" data-game-switch><?php foreach ($s['apps'] as $game): ?><option value="<?=e($app->path('/admin/').'?game_id='.$game['game_id'])?>" <?=$game['game_id']===$gameID?'selected':''?>><?=e($game['name'])?> · ID <?=e($game['game_id'])?></option><?php endforeach ?></select><button type="button" class="button quiet" data-dialog="game-dialog">＋ 新增游戏</button></section><div class="page-heading"><div><div class="eyebrow">RELEASE WORKSPACE</div><h1><?=e($g['name'])?></h1><p class="muted">管理这个游戏的更新包。所有游戏共用同一个接口，通过游戏 ID 区分。</p></div><a class="button primary" href="#upload">↑ 上传新版本</a></div>
<?php if ($flash): ?><div class="notice success" role="status"><?=e($flash)?></div><?php endif ?>
<details class="endpoint advanced-endpoint"><summary>更新接口与游戏 ID</summary><div class="endpoint-content"><div><span class="endpoint-label">共用更新接口 · 游戏 ID <?=e($g['game_id'])?></span><code><?=e($url)?></code></div><button class="button quiet" type="button" data-copy="<?=e($url)?>">复制地址</button></div></details>
<div class="metrics"><section class="metric"><span>当前线上版本</span><strong><?=$current?e($current['display_version']):'尚未发布'?></strong><small><?=$current?'发布序号 #'.e($current['sequence']):'上传并发布后开始分发'?></small></section><section class="metric"><span>分发包大小</span><strong><?=sizeLabel($current['artifact_bytes']??null)?></strong><small><?=$g['format']==='tipa'?'原始 TIPA':'由服务器自动准备安装资源'?></small></section><section class="metric"><span>更新接口</span><strong class="status-text"><span class="dot <?=$g['enabled']?'':'off'?>"></span><?=$g['enabled']?'已启用':'已停用'?></strong><small><?=count($releases)?> 条版本记录 · 配置 v<?=e($g['revision'])?></small></section></div>
