<details class="panel binding-panel"><summary>安装器绑定与接口设置</summary><div class="section-title"><div><span class="step-number">02</span><h2>当前构建绑定</h2></div></div><p class="muted compact">这些值与对应安装器保持一致。</p><dl class="bindings"><dt>游戏 ID</dt><dd><?=e($g['game_id'])?></dd><dt>预期 Bundle ID</dt><dd><?=e($g['bundle_id'])?></dd><dt>产物契约</dt><dd><?=e($g['profile_id'])?></dd><dt>发布格式</dt><dd><?=e($g['format'])?></dd></dl><div class="note-box"><?php if ($g['format']==='prepared-payload-v1'): ?><strong>上传成功 ≠ 已发布</strong><p>只上传对应游戏的辅助 TIPA，服务器自动准备和校验安装资源。处理完成后确认发布，安装器按游戏 ID 下载。</p><?php else: ?><strong>原始 TIPA 分发</strong><p>此配置直接分发 TIPA，请使用与此游戏匹配的安装器。</p><?php endif ?></div><details class="public-config"><summary>查看安装器公钥配置</summary><pre><?=e(json_encode(['game_id'=>$g['game_id'],'update_url'=>$url,'expected_bundle_id'=>$g['bundle_id'],'profile_id'=>$g['profile_id'],'key_id'=>$app->config['key_id'],'public_key_base64'=>$app->config['sign_public'],'native_public_key_base64'=>$app->config['native_sign_public']],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT))?></pre></details><form method="post" action="<?=MTX\Http::escape($app->path('/admin/action.php'))?>" data-confirm="确认切换这个游戏的更新接口状态？"><?php fields('toggle',$gameID,['revision'=>$g['revision']]) ?><button class="text-button" type="submit"><?=$g['enabled']?'停用此游戏接口':'启用此游戏接口'?></button></form></details></div>
<section class="versions"><div class="section-title"><div><span class="step-number">03</span><h2>版本记录</h2><span class="count"><?=count($releases)?></span></div><span class="muted">文件不可变 · 发布序号递增</span></div>
<?php if (!$releases): ?><div class="empty-state"><span class="empty-icon">↥</span><h3>准备好你的第一个版本</h3><p>上传 TIPA 后，版本号、包大小和检查状态会出现在这里。</p><a href="#upload" class="text-button">上传第一个更新包 →</a></div><?php endif ?>
<div id="release-table" aria-label="版本列表"></div><?php foreach ($releases as $r): $isCurrent=$g['current_release_id']===$r['release_id']; $prep=$r['preparation']??['status'=>'queued']; $prepLabel=['queued'=>'等待自动处理','processing'=>'正在自动处理','failed'=>'处理未完成'][$prep['status']]??'等待自动处理'; ?><article class="release-card" id="release-<?=e($r['release_id'])?>" data-release-id="<?=e($r['release_id'])?>"><details class="release-detail"><summary>版本 <?=e($r['display_version'])?> · <?=e($labels[$r['state']])?> · 查看详情与操作</summary><div class="release-header"><div class="version-identity"><span class="version-icon">↗</span><div><h3>版本 <?=e($r['display_version'])?> <span class="badge <?=e($r['state'])?>"><?=$isCurrent?'当前线上':e($r['state']==='draft'?$prepLabel:$labels[$r['state']])?></span></h3><p class="muted">Build <?=e($r['bundle_version'])?> <span>·</span> <?=e(dateLabel($r['created_at']))?></p></div></div><strong class="release-size"><?=sizeLabel($r['source_bytes'])?></strong></div><?php if (trim($r['changelog']??'')!==''): ?><p class="release-log"><strong>后台备注：</strong><?=nl2br(e($r['changelog']))?></p><?php endif ?><div class="release-meta"><span><?=$r['sequence']?'发布 #'.e($r['sequence']):'尚未分配发布序号'?></span></div><details class="hash-details"><summary>文件摘要与记录 ID</summary><p>源包 SHA-256 <code><?=e($r['source_sha256'])?></code></p><p>分发 SHA-256 <code><?=e($r['artifact_sha256']??'待准备')?></code></p><p>记录 ID <code><?=e($r['release_id'])?></code></p></details><div class="release-actions">
<?php if ($r['state']==='draft'): ?><div class="automatic-preparation"><strong><?=e($prepLabel)?></strong><p class="muted"><?=e(($prep['status']??'')==='failed'?($prep['error']??'自动处理未完成，请重试。'):'服务器会自动处理这份 TIPA，无需再上传其他文件。通常一分钟内开始，请稍后刷新。')?></p><a class="button quiet" href="<?=e($app->path('/admin/').'?game_id='.$gameID)?>">刷新处理状态</a><?php if (($prep['status']??'')==='failed'): ?><form method="post" action="<?=e($app->path('/admin/action.php'))?>"><?php fields('prepare_retry',$gameID,['release_id'=>$r['release_id']]) ?><button class="button" type="submit">重试自动处理</button></form><?php endif ?></div>
<?php elseif ($r['state']==='ready'): ?><form method="post" action="<?=MTX\Http::escape($app->path('/admin/action.php'))?>" class="publish-form" data-confirm="发布后，此游戏的固定接口会切换到这个版本。确认发布？"><?php fields('publish',$gameID,['release_id'=>$r['release_id'],'revision'=>$g['revision']]) ?><label class="checkbox"><input type="checkbox" name="confirmed" value="1" required>已完成对应安装器的兼容测试</label><button class="button primary" type="submit" <?=$g['enabled']?'':'disabled'?>>发布此版本 →</button></form>
<?php else: ?><form method="post" action="<?=MTX\Http::escape($app->path('/admin/action.php'))?>"><?php fields('republish',$gameID,['release_id'=>$r['release_id']]) ?><button class="button quiet" type="submit">复制为新发布草稿</button></form><?php endif ?>
<?php if ($r['state']!=='withdrawn'): ?><form method="post" action="<?=MTX\Http::escape($app->path('/admin/action.php'))?>" data-confirm="确认下架此版本？若为当前线上版本，接口将显示暂无发布。不会自动切回旧版。"><?php fields('withdraw',$gameID,['release_id'=>$r['release_id'],'revision'=>$g['revision']]) ?><button class="text-button danger" type="submit">下架</button></form><?php endif ?></div></details></article><?php endforeach ?></section>
<details class="panel audit"><summary>最近操作记录 <span class="muted">保留最近 1,000 条</span></summary><div class="audit-list"><?php foreach (array_slice(array_reverse($s['audit']),0,20) as $event): ?><div><time><?=e(dateLabel($event['time']))?></time><strong><?=e($event['action'])?></strong><span><?=e($event['target'])?></span></div><?php endforeach ?><?php if (!$s['audit']): ?><p class="muted">暂无操作记录。</p><?php endif ?></div></details><footer class="page-footer">MTX 更新中心 <span>只管理发布 · 安装行为由客户端确认执行</span></footer></main>
